import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.mrTIYZc5.js";const u=JSON.parse('{"title":"Design Principles","description":"","frontmatter":{},"headers":[],"relativePath":"guide/design-principles.md","filePath":"guide/design-principles.md"}'),r={name:"guide/design-principles.md"};function o(s,e,l,c,d,h){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h1><p>Docker Secret Operator (DSO) is guided by a set of core principles that prioritize security, operational simplicity, and native integration. Every feature and architectural decision must align with these pillars.</p><hr><h2 id="_1-zero-persistence-by-default" tabindex="-1">1. Zero Persistence by Default <a class="header-anchor" href="#_1-zero-persistence-by-default" aria-label="Permalink to &quot;1. Zero Persistence by Default&quot;">​</a></h2><p>Secrets should never touch persistent storage.</p><ul><li><strong>The Rule</strong>: No <code>.env</code> files, no host-path mounts for plaintext secrets, and no secret data in image layers.</li><li><strong>The Implementation</strong>: Secrets are held in the agent&#39;s RAM and injected via <code>tmpfs</code> mounts or the <code>CopyToContainer</code> API.</li></ul><h2 id="_2-event-driven-reconciliation" tabindex="-1">2. Event-Driven Reconciliation <a class="header-anchor" href="#_2-event-driven-reconciliation" aria-label="Permalink to &quot;2. Event-Driven Reconciliation&quot;">​</a></h2><p>DSO is not a one-time &quot;fetch and forget&quot; tool. It is a state reconciler.</p><ul><li><strong>The Rule</strong>: The system must respond immediately to changes in either the source (Vault) or the destination (Docker).</li><li><strong>The Implementation</strong>: A continuous Control Loop (Watch-Analyze-Inject) ensuring the &quot;Actual State&quot; always matches the &quot;Desired State.&quot;</li></ul><h2 id="_3-docker-native-experience" tabindex="-1">3. Docker-Native Experience <a class="header-anchor" href="#_3-docker-native-experience" aria-label="Permalink to &quot;3. Docker-Native Experience&quot;">​</a></h2><p>DSO should feel like a first-class citizen of the Docker ecosystem.</p><ul><li><strong>The Rule</strong>: No complex external dependencies or sidecar architectures where possible.</li><li><strong>The Implementation</strong>: Native CLI plugin support (<code>docker dso</code>), metadata-driven discovery via Labels, and interaction through the standard Docker Unix socket.</li></ul><h2 id="_4-least-privilege-machine-identity" tabindex="-1">4. Least Privilege / Machine Identity <a class="header-anchor" href="#_4-least-privilege-machine-identity" aria-label="Permalink to &quot;4. Least Privilege / Machine Identity&quot;">​</a></h2><p>Human intervention in secret management should be minimized to prevent credential leakage.</p><ul><li><strong>The Rule</strong>: Eliminate static credentials (API Keys, Client Secrets) on the host.</li><li><strong>The Implementation</strong>: Deep integration with cloud-native identity providers (AWS IAM, Azure Managed Identity) so the host &quot;is&quot; the credential.</li></ul><h2 id="_5-atomic-and-non-destructive-rotation" tabindex="-1">5. Atomic and Non-Destructive Rotation <a class="header-anchor" href="#_5-atomic-and-non-destructive-rotation" aria-label="Permalink to &quot;5. Atomic and Non-Destructive Rotation&quot;">​</a></h2><p>Secret updates should never leave an application in a partially-configured or broken state.</p><ul><li><strong>The Rule</strong>: Updates must be all-or-nothing and verified for health.</li><li><strong>The Implementation</strong>: Tar-streamed injection and intelligent rotation strategies that wait for health-checks before removing old container instances.</li></ul><hr><h2 id="why-these-principles-matter" tabindex="-1">Why These Principles Matter <a class="header-anchor" href="#why-these-principles-matter" aria-label="Permalink to &quot;Why These Principles Matter&quot;">​</a></h2><p>By strictly adhering to these principles, DSO provides a security model that is significantly more robust than traditional Docker secret management, while maintaining the simplicity that makes Docker the preferred choice for many engineering teams.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: See how these principles are implemented.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: Detailed threat mitigations.</li><li><strong><a href="/docs/guide/production-readiness.html">Production Readiness</a></strong>: Deploying DSO in high-security environments.</li></ul>',23)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
